package com.example.solarfarm.controller;
import com.example.solarfarm.common.Dtos; import com.example.solarfarm.domain.*; import com.example.solarfarm.repository.AlertRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/alerts") public class AlertController { private final AlertRepository repo; public AlertController(AlertRepository r){repo=r;} @GetMapping public List<Dtos.AlertResponse> all(){return repo.findAll().stream().map(this::map).toList();} @PatchMapping("/{id}/acknowledge") public Dtos.AlertResponse acknowledge(@PathVariable Long id){Alert a=repo.findById(id).orElseThrow();a.acknowledge();return map(repo.save(a));} private Dtos.AlertResponse map(Alert a){return new Dtos.AlertResponse(a.getId(),a.getPanel().getPanelId(),a.getFaultType(),a.getSeverity(),a.getMessage(),a.getStatus().name(),null);} }
